        if (s[0] == '?' || s[0] == ch) {
            odd[c] = 1;
        }
    }

    // 从第二个字符开始动态规划
    for (int i = 1; i < (int)s.size(); i++) {
        long long newOdd[2] = {0, 0};
        long long newEven[2] = {0, 0};

        for (int c = 0; c < 2; c++) {
            char ch = c == 0 ? '0' : '1';
            if (s[i] != '?' && s[i] != ch) {
                continue;
            }

            // 继续放相同字符：当前段长度奇偶性翻转
            newOdd[c] = (newOdd[c] + even[c]) % MOD;
